const money=(value:number|null|undefined)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(value??0));
const planCopy={core:{name:'Core',price:'$497',limit:'500 invoices',overage:'$0.75 per additional invoice',features:['Up to 3 users','Up to 3 recipients','1 intake flow']},growth:{name:'Growth',price:'$997',limit:'1,500 invoices',overage:'$0.50 per additional invoice',features:['Unlimited users and recipients','Exception reprocessing','Administrative controls','Multiple senders and flows']},scale:{name:'Scale',price:'$1,497',limit:'3,000 invoices',overage:'$0.50 per additional invoice',features:['Unlimited users and recipients','Exception reprocessing','Administrative controls','Multiple senders and flows']}} as const;
const benefits=[['⌁','Stop overpaying carriers','Every charge is checked against the rate con before payment. Mismatches surface instead of being buried.'],['◷','Recover revenue you earned','Detention, liftgate and layover accessorials you performed but never billed are identified.'],['▤','Catch duplicate invoices','Every load is cross-referenced so repeated carrier billing is flagged automatically.'],['✓','Review exceptions, not paperwork','Your team sees only what needs attention instead of comparing invoices one by one.'],['◎','Verify carrier authority','FMCSA operating status is checked as part of every audit.'],['≡','Keep a complete audit trail','Every finding records what was flagged, why it matters and the evidence behind it.']] as const;
const faqs=[['What exactly does Olympian audit?','The free audit checks invoices for duplicates, carrier authority, MC mismatches, banking changes and invoice-level anomalies. Ongoing coverage adds rate confirmations and PODs to reconcile charges, verify accessorials and detect earned revenue that was never billed.'],['How does ongoing auditing work?','Forward invoices to your private intake address. Olympian receives the documents, runs the checks and sends only the exceptions to your team for a final decision.'],['Do we need to change how our team works?','No. Setup maps your current AP rules once. Documents then arrive through your intake flow and exceptions go to the recipients you choose.'],['Does Olympian dispute charges for us?','No. Olympian provides the finding and its evidence. Your team keeps control of carrier communication and every payment decision.'],['Is our data protected?','Documents are encrypted in transit and at rest, isolated by workspace, never sold or shared, and deleted under the retention policy.'],['Do you integrate with our TMS?','TMS exports work today without a direct integration. Send the file your system already produces and Olympian handles the structured import.']] as const;
function resultPageLegacy(result:repositoryResult,token:string){
 const report=result.result!;const groups=new Map<string,number>();for(const finding of report.exceptions)groups.set(finding.rule_label,(groups.get(finding.rule_label)??0)+1);
 const findings=[...groups.entries()].slice(0,8).map(([label,count])=>`<div class="finding"><strong>${escapeHtml(label)}</strong><span>${count} ${count===1?'finding':'findings'}</span></div>`).join('')||'<div class="finding"><strong>No billing risks detected</strong><span>0 findings</span></div>';
 const q=encodeURIComponent(token);const billingSelector=`<form id="result-checkout" method="post" action="/free-audit/result/checkout?token=${q}"></form><fieldset class="period"><legend>Billing period</legend><label><input form="result-checkout" type="radio" name="period" value="monthly" checked> Monthly</label><label><input form="result-checkout" type="radio" name="period" value="semiannual"> 6 months</label><label><input form="result-checkout" type="radio" name="period" value="annual"> Annual</label></fieldset>`;const planCards=billingSelector+(Object.entries(planCopy) as [keyof typeof planCopy,(typeof planCopy)[keyof typeof planCopy]][]).map(([code,plan])=>`<article class="plan-card ${code===result.recommended_plan?'recommended':''}">${code===result.recommended_plan?'<b class="badge">★ Recommended for your volume</b>':''}<h3>${plan.name}</h3><div class="price">${plan.price}<small>/month</small></div><div class="allowance"><strong>${plan.limit}</strong><span>included each month</span><b>${plan.overage}</b></div><ul>${plan.features.map(feature=>`<li>✓ ${feature}</li>`).join('')}</ul><button form="result-checkout" class="action ${code===result.recommended_plan?'secondary':''}" type="submit" name="plan" value="${code}">Choose ${plan.name}</button></article>`).join('');
 return `<main class="result"><span class="eyebrow">Your private free audit</span><h1>${money(report.valor_total_under_review)} deserves a closer look.</h1><p class="lead">We reviewed the eligible invoices submitted by ${escapeHtml(result.company_name)}. These automated findings are a review queue—not a final payment decision.</p><section class="stats" aria-label="Audit summary"><div class="stat"><strong>${money(report.valor_total_under_review)}</strong><span>under review</span></div><div class="stat"><strong>${report.total_exceptions}</strong><span>findings</span></div><div class="stat"><strong>${report.total_invoices_processed}</strong><span>invoices reviewed</span></div></section><div class="downloads"><a class="action secondary" href="/free-audit/result?token=${q}&format=pdf">Download PDF</a><a class="action secondary" href="/free-audit/result?token=${q}&format=csv">Download CSV</a></div><section class="section"><span class="eyebrow">What we found</span><h2>The issues surfaced in this submission.</h2><div class="findings">${findings}</div></section></main><section class="bridge"><span class="eyebrow">This was one submission</span><h2>What happens with the next invoice?</h2><p class="lead">The free audit is a snapshot. Olympian reviews every carrier invoice as it arrives and surfaces only the exceptions your team needs to decide.</p><div class="steps"><div class="step"><b>01</b><h3>Forward the invoice</h3><p>Use your private Olympian inbox.</p></div><div class="step"><b>02</b><h3>Olympian audits it</h3><p>Charges, carrier data and documents are checked.</p></div><div class="step"><b>03</b><h3>Exceptions surface</h3><p>Potential issues are separated from clean invoices.</p></div><div class="step"><b>04</b><h3>Your team decides</h3><p>You retain the final payment decision.</p></div></div><div class="compare"><div class="compare-card"><span class="eyebrow">Your free audit</span><h3>Invoices only</h3><p>One submission checking duplicates, authority, MC information, banking changes and invoice-level anomalies.</p></div><div class="compare-card full"><span class="eyebrow">Full Olympian</span><h3>Invoice + rate con + POD</h3><p>Continuous charge reconciliation, detention and accessorial verification, missing-charge and unbilled-revenue detection, plus exception management.</p></div></div></section><main class="result"><section class="section"><h2>Everything your AP process is missing.</h2><div class="benefits">${benefits.map(([icon,title,body])=>`<article class="benefit"><i>${icon}</i><h3>${title}</h3><p>${body}</p></article>`).join('')}</div></section><section class="section"><div class="security"><div><span class="eyebrow">Security</span><h2>Your invoices are confidential. Full stop.</h2><p>Encrypted in transit and at rest, scoped to your workspace, covered by a visible access trail and never sold or shared.</p></div><ul><li>Encrypted storage</li><li>Workspace isolation</li><li>Visible access log</li><li>Private intake address</li><li>Deletion on request</li><li>Never sold or shared</li></ul></div></section><section class="section"><h2>Everything you need to know.</h2><div class="faq">${faqs.map(([question,answer],index)=>`<details ${index===0?'open':''}><summary>${question}</summary><p>${answer}</p></details>`).join('')}</div></section><section class="section plans"><span class="eyebrow">Choose ongoing coverage</span><h2>Every plan audits the same way. Capacity and controls grow with you.</h2><div class="plan-grid">${planCards}</div><p class="privacy">The highlighted plan is based on the load volume provided with this audit. This private result remains available through the D+30 follow-up; submitted documents are deleted after 30 days.</p></section></main>`;
}
const billingPrice=(plan:PlanCode,period:BillingPeriod)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:0,maximumFractionDigits:2}).format(prices[plan][period].amount/100);
